  "q": "【図】(図7)のように、定滑車を使って100gのおもりをつり合わせます。ひもをAの方向に引いてつり合わせたとき、手で引く力は何gですか。Bの方向ではどうですか。下から選び、それぞれ記号で答えなさい。(ア)100g (イ)100gより大きい (ウ)100gより小さい",
