  "subj": "社会",
  "u": "夏期講習 復習編1.日本の食料生産",
  "q": "大都市周辺で、新鮮な野菜や花などを新鮮なうちに消費地に届けられるように行われる農業を何といいますか。また、これについて述べた文として正しくないものを選びなさい。ア東京など大都市周辺でさかん　イ新鮮なうちに消費地に届けられる　ウ大都市で人気の高いマンゴーやパイナップルの生産を増やしている　エ年間を通じて出荷できるよう複数の農産物を生産している",
